source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');source(file.path(S,'model_helpers.R'));b<-qread(file.path(B,'objects/pseudobulk.qs'),nthreads=1);pr<-b$profiles;plan<-rd('model_plan.tsv')
statuses<-list();summaries<-list();memberships<-list();designs<-list();fits<-list();cand<-list();focus<-c('NECTIN2','PVR','VEGFA','VEGFB','VEGFC','PGF','ANGPT1','ANGPT2','TGFB1','TGFB2','CXCL12','MDK','MIF','LGALS9','TIGIT','PVRIG','CD226','FLT1','KDR','FLT4','NRP1','NRP2','TEK')
for(ii in seq_len(nrow(plan))){p<-plan[ii];id<-p$model_id;sf<-tb(paste0('de/',id,'_status.tsv'));if(!file.exists(sf))stop('Unfinished model ',id);st<-fread(sf)
 if(st$status=='not_evaluable'){
 sel<-pr[(if(p$patient=='main')main_patient else replacement_patient)&n_cells>=p$min_cells];if(p$omit_dataset!='none')sel<-sel[dataset!=p$omit_dataset];if(p$only_dataset!='ALL')sel<-sel[dataset==p$only_dataset]
 if(p$kind=='receiver')sel<-sel[profile_type==p$target]else {if(p$subset=='common'){ok<-sel[profile_type%in%c('H50','H10','H05','L50'),.N,by=sample_uid][N==4,sample_uid];sel<-sel[sample_uid%in%ok]};ok<-sel[profile_type%in%c(p$target,'L50'),.N,by=sample_uid][N==2,sample_uid];sel<-sel[sample_uid%in%ok&profile_type%in%c(p$target,'L50')]}
 st[,`:=`(n_profiles=nrow(sel),n_specimens=uniqueN(sel$sample_uid),n_recorded_patient_units=uniqueN(sel$patient_uid_recorded),n_datasets=uniqueN(sel$dataset),datasets=paste(sort(unique(sel$dataset)),collapse=';'))];if(nrow(sel))memberships[[id]]<-cbind(data.table(model_id=id),sel)
 if(nrow(sel)==0){st[,reason:='no_eligible_profiles']}else if(uniqueN(sel$patient_uid_recorded)<4){st[,reason:='fewer_than_4_recorded_patient_units']}else{
 if(p$kind=='Epi'){sel[,specimen:=factor(sample_uid)];sel[,state:=factor(ifelse(profile_type=='L50','Low','High'),levels=c('Low','High'))];dd<-model.matrix(~specimen+state,sel)}else{sel[,exposure_z:=get(paste0(p$exposure,'_z'))];sel[,dataset_factor:=factor(dataset)];dd<-if(uniqueN(sel$dataset)>1)model.matrix(~dataset_factor+exposure_z,sel)else model.matrix(~exposure_z,sel)}
 st[,`:=`(design_rank=qr(dd)$rank,design_columns=ncol(dd),residual_df=nrow(dd)-qr(dd)$rank,reason=if(qr(dd)$rank<ncol(dd))'rank_deficient_dataset_exposure'else'residual_df_below_frozen_3')];designs[[id]]<-data.table(model_id=id,profile_id=sel$profile_id,design_row=apply(dd,1,function(z)paste(z,collapse=';')),design_columns=paste(colnames(dd),collapse=';'))
 }

 }else if(st$status=='completed'){
 fit<-qread(file.path(B,'objects/model_parts',paste0(id,'.qs')),nthreads=1);fits[[id]]<-fit;sel<-fit$profiles;memberships[[id]]<-cbind(data.table(model_id=id),sel);designs[[id]]<-data.table(model_id=id,profile_id=sel$profile_id,design_row=apply(fit$design,1,function(z)paste(z,collapse=';')),design_columns=paste(colnames(fit$design),collapse=';'))
 tt<-rd(paste0('de/',id,'.tsv.gz'));tt[,signed_stat:=sign(logFC)*sqrt(pmax(F,0))];put(tt,paste0('de/',id,'.tsv.gz'));summaries[[id]]<-tt[,.(n_tested=.N,n_positive=sum(FDR<.05&logFC>0),n_negative=sum(FDR<.05&logFC<0),min_p=min(PValue))][,model_id:=id]
 }
 statuses[[id]]<-st
}
status<-rbindlist(statuses,fill=TRUE);put(status,'model_status.tsv');put(rbindlist(memberships,fill=TRUE),'model_membership.tsv.gz');put(rbindlist(designs,fill=TRUE),'model_design_matrices.tsv.gz');put(rbindlist(summaries,fill=TRUE),'de_summary.tsv') # Per-model compact caches already contain these inputs; do not duplicate the full list.
for(k in c('Epi','receiver')){ids<-plan[primary&kind==k,model_id];tt<-rbindlist(lapply(ids,function(id){f<-tb(paste0('de/',id,'.tsv.gz'));if(file.exists(f))fread(f)else NULL}));if(nrow(tt)){tt[,joint_main_q:=p.adjust(PValue,'BH')];for(id in unique(tt$model_id))put(tt[model_id==id],paste0('de/',id,'.tsv.gz'))}}
for(id in plan$model_id){p<-plan[model_id==id];f<-tb(paste0('de/',id,'.tsv.gz'));tt<-if(file.exists(f))fread(f)[gene%in%focus]else data.table(gene=character());v<-merge(data.table(gene=focus),tt,by='gene',all.x=TRUE);v[,model_id:=id];v<-merge(v,p,by='model_id');v<-merge(v,status[,.(model_id,n_specimens,n_recorded_patient_units,n_datasets,status,reason)],by='model_id');v[,gene_status:=ifelse(status!='completed','model_not_evaluable',ifelse(is.na(logFC),'not_expression_testable','tested'))];cand[[id]]<-v};put(rbindlist(cand,fill=TRUE),'candidate_de_effects.tsv')
# TF RNA retains full-gene DE FDR, separate from activity-model FDR.
tfs<-unique(fread(file.path(REF,'collectri.tsv'))$source);tfout<-rbindlist(lapply(names(fits),function(id){tt<-rd(paste0('de/',id,'.tsv.gz'));z<-merge(data.table(source=tfs),tt,by.x='source',by.y='gene',all.x=TRUE);z[,`:=`(model_id=id,rna_status=ifelse(is.na(logFC),'not_tested_or_complex','tested'))];z}));put(tfout,'TF_RNA_de.tsv.gz')
# Specimen influence is descriptive paired logCPM, not a new patient-level edgeR P value.
infl<-list();for(id in plan[primary&kind=='Epi',model_id]){f<-fits[[id]];if(is.null(f))next;pp<-f$profiles;genes<-intersect(focus,rownames(f$logCPM));for(g in genes){v<-data.table(sample_uid=pp$sample_uid,state=pp$state,value=f$logCPM[g,]);v<-dcast(v,sample_uid~state,value.var='value');v[,difference:=High-Low];for(s in v$sample_uid)infl[[length(infl)+1]]<-data.table(model_id=id,gene=g,omitted_specimen=s,full_mean_paired_logCPM=mean(v$difference),leave_one_mean_paired_logCPM=mean(v[sample_uid!=s,difference]),n_pairs=nrow(v)-1)}};put(rbindlist(infl),'candidate_single_specimen_influence.tsv')
exaudit<-rbindlist(lapply(names(fits),function(id){f<-fits[[id]];pp<-f$profiles;dd<-f$design;z<-data.table(model_id=id,rank=qr(dd)$rank,n_columns=ncol(dd),residual_df=nrow(dd)-qr(dd)$rank,condition_number=kappa(dd));if(f$model$kind=='receiver'){xx<-pp$exposure_z;ff<-if(uniqueN(pp$dataset)>1)lm(xx~factor(pp$dataset))else lm(xx~1);z[,`:=`(exposure_R2_dataset=if(uniqueN(pp$dataset)>1)summary(ff)$r.squared else 0,exposure_SD_total=sd(xx),exposure_SD_within_dataset=sd(residuals(ff)))]};z}),fill=TRUE);put(exaudit,'model_exposure_confounding.tsv')
